from dataclasses import dataclass
from datetime import datetime
from typing import Optional


class PromotionExpiredError(Exception):
    """Provisional policy: expired promotions reject the order (pending product decision)."""

    def __init__(self, code: str):
        super().__init__(f"Promotion {code!r} has expired")
        self.code = code


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: int
    expires_at: datetime


def order_total(subtotal_cents: int, promotion: Optional[Promotion], now: datetime) -> int:
    if promotion is None:
        return subtotal_cents
    if now >= promotion.expires_at:
        raise PromotionExpiredError(promotion.code)
    return subtotal_cents - subtotal_cents * promotion.percent_off // 100
