cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
import pytest
from checkout import Promotion, PromotionExpiredError, order_total

NOW = datetime(2026, 10, 20, 12, 0)
def promo(delta): return Promotion("SAVE10", 10, NOW + delta)

def test_no_promotion():
    assert order_total(1000, None, NOW) == 1000

def test_valid_promotion_applies():
    assert order_total(1000, promo(timedelta(days=1)), NOW) == 900

def test_expired_promotion_rejects_order():
    with pytest.raises(PromotionExpiredError) as e:
        order_total(1000, promo(timedelta(seconds=-1)), NOW)
    assert e.value.code == "SAVE10"

def test_promotion_expiring_exactly_now_is_expired():
    with pytest.raises(PromotionExpiredError):
        order_total(1000, promo(timedelta(0)), NOW)
E
